import { useDispatch, useSelector } from "react-redux";
import { productSelector } from "../../store/selectors/productSelectors";
import { getProductsMiddleWare } from "../../store/store";
import { useEffect } from "react";

import style from "./Products.module.css";

function Products() {
  const dispatch = useDispatch();
  const data = useSelector(productSelector);
  useEffect(() => {
    dispatch(getProductsMiddleWare());
  }, []);
  console.log(data);

  return (
    <div className={style.mainProd}>
      {data?.map((elm) => {
        return (
          <div key={elm.id} className="">
            <p>{elm.title}</p>
            <img src={elm.images[0]} alt="" />
          </div>
        );
      })}
    </div>
  );
}

export default Products;
